		// array pointer need no further bounds checks.
		b := (*[16]uint64)(xs)
		n += bits.OnesCount64(b[0]) + bits.OnesCount64(b[1]) +
			bits.OnesCount64(b[2]) + bits.OnesCount64(b[3]) +
			bits.OnesCount64(b[4]) + bits.OnesCount64(b[5]) +
