			bits.OnesCount64(b[10]) + bits.OnesCount64(b[11]) +
			bits.OnesCount64(b[12]) + bits.OnesCount64(b[13]) +
			bits.OnesCount64(b[14]) + bits.OnesCount64(b[15])
		xs = xs[16:]
	}
	// At most 15 words remain; index directly, with no reslicing.
	if l := len(xs); l >= 8 {
